# -*- coding: utf-8 -*-
# ٥٠ مشكلة تربوية شائعة: الوصف، والتفسير العلمي المبسّط، وخطوات الحل، وعبارات بديلة، وكلمة بحث في المكتبة.
# التصنيف: cat. القيم: صغار، سلوك، مشاعر، دراسة، عبادة، مراهقة، أمان، إخوة، عادات
P = []
def p(cat, t, d, sci, steps, q, say=None, age=''):
    P.append(dict(cat=cat, t=t, d=d, sci=sci, steps=steps, q=q, say=say or [], age=age))

# ---------- الصغار (٠–٥) ----------
p('صغار', 'نوبات الغضب والصراخ (التشنّج)', 'يرمي الطفل نفسه أرضاً ويصرخ إذا مُنع من شيء.', 'الجزء المسؤول عن ضبط الانفعال في الدماغ (القشرة الأمامية) لا يكتمل إلا متأخراً، فالطفل بين ١ و٤ سنوات لا يملك بعد أدوات تهدئة نفسه، ويحتاج إلى «تهدئة مشتركة» من الكبير.', ['حافظ على هدوئك؛ أنت مرآة الطفل.', 'تأكد من سلامته، ولا تتفاوض أثناء النوبة.', 'سمِّ شعوره: «أنت غاضب لأنك تريد الحلوى».', 'لا تستجب للطلب بسبب الصراخ، وإلا تعلّم أن الصراخ ينجح.', 'بعد هدوئه: ضمّة، ثم علّمه كلمة يقولها بدل الصراخ.', 'قلّل المسببات: الجوع والنعاس والتعب.'], 'الغضب', [['اسكت وإلا…', 'أنا معك، لما تهدأ نتكلم']], '١–٥')
p('صغار', 'العض والضرب عند الصغار', 'يعض أو يضرب أطفالاً آخرين أو والديه.', 'سلوك شائع قبل اكتمال اللغة؛ فالطفل يعبّر بجسده عما لا يستطيع قوله، أو يجرّب ردّة الفعل.', ['أوقفه فوراً بهدوء وحزم: «لا نعض، العض يؤلم».', 'التفت إلى المتضرر واهتم به أمامه، لا إلى المعتدي.', 'علّمه بديلاً: «قل: لا! أو تعال ناديني».', 'لا تعضّه أو تضربه لتعلّمه، فهذا يعلّمه العكس.', 'لاحظ متى يتكرر (تعب، ازدحام) وتجنّب تلك الظروف.'], 'الرفق', [], '١–٤')
p('صغار', 'رفض الطعام وانتقائية الأكل', 'يأكل أصنافاً محدودة ويرفض الجديد.', 'الخوف من الأطعمة الجديدة مرحلة طبيعية في النمو، وقد يحتاج الطفل أن يرى الصنف ويتذوقه ١٠–١٥ مرة قبل أن يقبله.', ['قدّم الصنف الجديد بكمية صغيرة بجانب طعام يحبه.', 'لا تُجبره ولا ترشُه بالحلوى ليأكل.', 'كلوا معاً على المائدة؛ القدوة أقوى من الأمر.', 'أشركه في التسوّق والتحضير.', 'حدّد أوقات الوجبات، وقلّل العصير والوجبات الخفيفة بينها.', 'راجع الطبيب إن كان وزنه أو نموه متأثراً.'], 'الطعام', [['كُل وإلا ما في لعب', 'ذُق لقمة واحدة، وإن ما عجبك لا بأس']], '٢–٨')
p('صغار', 'صعوبة النوم والاستيقاظ ليلاً', 'يرفض النوم أو يستيقظ كثيراً ويأتي لغرفة والديه.', 'الروتين الثابت قبل النوم يساعد الجسم على إفراز هرمون النوم (الميلاتونين)، والشاشات قبل النوم تؤخره.', ['روتين ثابت كل ليلة: حمام، أسنان، أذكار النوم، قصة، ثم إطفاء.', 'وقت نوم ثابت حتى في الإجازات تقريباً.', 'لا شاشات قبل النوم بساعة.', 'إن استيقظ: أرجعه لسريره بهدوء وبأقل كلام.', 'نور خافت وصوت هادئ إن كان يخاف.'], 'النوم', [], '١–١٠')
p('صغار', 'التدريب على استخدام الحمّام', 'تأخر أو صعوبة في ترك الحفاض.', 'معظم الأطفال يكونون مستعدين بين ٢ و٣ سنوات، وعلامات الاستعداد أهم من العمر: البقاء جافاً ساعتين، والانزعاج من الحفاض، وفهم التعليمات.', ['ابدأ عند ظهور علامات الاستعداد لا بضغط الآخرين.', 'أوقات ثابتة: بعد الاستيقاظ والطعام.', 'امدح المحاولة، ولا تعاقب على الحوادث أبداً.', 'ملابس سهلة الخلع.', 'علّمه آداب الخلاء والدعاء تدريجياً.', 'إن تراجع بعد نجاح (كمولود جديد) فاصبر فهو مؤقت.'], 'الطهارة', [], '٢–٤')
p('صغار', 'التبول الليلي', 'يبلل فراشه ليلاً بعد سن الخامسة.', 'التبول الليلي شائع حتى سن ٥–٦ وله أسباب جسدية غالباً (نضج المثانة، والوراثة، والنوم العميق)، وليس كسلاً ولا عناداً.', ['لا تعاقب ولا تُخجله أمام إخوته.', 'قلّل الشرب قبل النوم بساعة، ودعه يدخل الحمام قبل النوم.', 'غطاء مقاوم للماء للفراش.', 'جدول نجوم لليالي الجافة.', 'استشر طبيب الأطفال بعد السادسة أو إن عاد فجأة بعد انقطاع.'], 'الرفق', [], '٥+')
p('صغار', 'التعلق الشديد بالأم وقلق الانفصال', 'يبكي بشدة عند ذهاب الأم أو دخول الروضة.', 'قلق الانفصال مرحلة طبيعية بين ٨ أشهر و٣ سنوات، ويخف كلما تعلّم الطفل أن أمه تذهب وتعود فعلاً.', ['ودّعه دائماً ولا تتسلل خفية؛ التسلل يزيد القلق.', 'وداع قصير ثابت: «أحبك، أرجع بعد العصر».', 'ابدأ بفترات غياب قصيرة ثم أطِلها.', 'عُد في الموعد الذي قلته.', 'غرض من البيت يحمله معه.'], 'الرحمة', [['لو بكيت ما أرجع', 'سأرجع بعد النوم، وأنت بأمان هنا']], '١–٥')
p('صغار', 'تأخر الكلام', 'لا يتكلم كلمات كأقرانه.', 'الكلام يتطور بالتفاعل الحي: الحديث المباشر والقراءة المشتركة، والشاشات لا تعوّض ذلك بل ترتبط كثرتها بتأخر اللغة.', ['تحدّث معه طوال اليوم وصِف ما تفعل.', 'اقرأ له قصصاً مصورة يومياً.', 'قلّل الشاشات أو امنعها قبل سنتين.', 'لا تلبِّ طلبه بالإشارة فقط؛ شجّعه على الكلمة.', 'إن لم يقل كلمات مفيدة عند ١٨ شهراً أو جملتين قصيرتين عند سنتين: افحص السمع وراجع أخصائي التخاطب.'], 'الكلام', [], '١–٤')

# ---------- السلوك ----------
p('سلوك', 'العناد', 'يرفض الأوامر ويقول «لا» دائماً.', 'العناد حاجة طبيعية لإثبات الذات والاستقلال، ويظهر بقوة بين ٢ و٤ سنوات وفي المراهقة. وكثرة الأوامر تزيده.', ['أعطه خيارين مقبولين بدل الأمر المباشر.', 'قلّل الأوامر واجعلها واضحة وقصيرة.', 'لا تدخل في صراع إرادات، وحافظ على هدوئك.', 'امدح كل تعاون مهما كان صغيراً.'], 'الرفق', [['البس الآن!', 'تلبس القميص الأزرق أم الأحمر؟']])
p('سلوك', 'الكذب', 'يكذب ليتجنّب العقاب أو ليحصل على شيء.', 'الكذب عند الصغير غالباً خوف من العقاب أو خيال واسع، وكلما اشتدت العقوبة على الاعتراف زاد الكذب.', ['كن قدوة في الصدق ولو في المزاح.', 'لا تعاقب بشدة على الاعتراف، بل اشكر الصدق.', 'فرّق بين خيال الطفل الصغير والكذب المقصود.', 'لا تسأل سؤالاً تعرف جوابه لتوقعه: قل «رأيتك فعلت كذا، كيف نصلحه؟».', 'احكِ قصصاً عن الصدق وثوابه.'], 'الصدق', [['أنت كذاب!', 'أنا أقدّر لما تقول الحقيقة حتى لو كانت صعبة']])
p('سلوك', 'السرقة وأخذ أغراض الآخرين', 'يأخذ أغراض إخوته أو زملائه دون إذن.', 'عند الصغار قبل ٦ سنوات لا يكتمل مفهوم الملكية بعد؛ أما بعدها فقد تكون رغبة أو تقليداً أو طلباً للاهتمام.', ['لا تصفه بالسارق.', 'علّمه مفهوم «هذا لي وهذا لغيري» واطلب الإذن.', 'أعِد الشيء معه لصاحبه واعتذرا.', 'ابحث عن السبب: حاجة؟ غيرة؟ ضغط أصدقاء؟', 'أعطه مصروفاً يدبّره.'], 'الأمانة', [['يا حرامي', 'هذا ليس لنا، نرجعه ونعتذر معاً']])
p('سلوك', 'الألفاظ البذيئة والشتم', 'يردد كلمات سيئة سمعها.', 'الطفل يقلّد ما يسمع، ويكرر الكلمة أكثر إذا لاحظ أنها تثير ردة فعل قوية.', ['لا تضحك ولا تنفعل؛ قل بهدوء: «هذه كلمة لا نقولها».', 'اعرف مصدرها: أصدقاء، شاشات، أقارب.', 'علّمه كلمات بديلة للتعبير عن الغضب.', 'كن قدوة في ألفاظك.', 'امدح الكلام الطيب.'], 'اللسان')
p('سلوك', 'الحركة الزائدة وقلة التركيز', 'لا يستقر في مكان ولا يكمل مهمة.', 'كثير من الأطفال كثيرو الحركة طبيعياً، لكن إذا كانت الحركة والاندفاع وتشتت الانتباه شديدة ومستمرة في البيت والمدرسة معاً لأكثر من ٦ أشهر فقد يكون «فرط الحركة وتشتت الانتباه»، ويُشخّصه المختص فقط.', ['وفّر له وقتاً يومياً للحركة واللعب الحر.', 'قسّم المهام إلى خطوات قصيرة مع استراحات.', 'روتين ثابت وتعليمات قصيرة واحدة تلو الأخرى.', 'قلّل الشاشات والسكريات.', 'إن أثّر في دراسته وعلاقاته فراجع طبيب الأطفال أو الطبيب النفسي للأطفال، ولا تشخّصه بنفسك.'], 'الصبر')
p('سلوك', 'العدوانية وضرب الآخرين', 'يضرب أصدقاءه أو إخوته عند الخلاف.', 'الطفل يتعلم العنف بالتقليد (من البيت أو الشاشات)، ويستعمله إذا لم يتعلم مهارات حل الخلاف.', ['أوقفه فوراً، وافصل بين الأطفال.', 'لا تضربه على الضرب.', 'علّمه تسمية مشاعره وطلب المساعدة.', 'تدرّبوا بالتمثيل على حل خلاف.', 'راقب الألعاب والمقاطع العنيفة.', 'كافئ اللعب الهادئ.'], 'الغضب')
p('سلوك', 'الأنانية وعدم المشاركة', 'يرفض أن يشارك ألعابه.', 'قبل سن ٣–٤ سنوات لا يفهم الطفل المشاركة بعد، وتنمو مع العمر بالتدريب لا بالإجبار.', ['لا تجبره على إعطاء أغلى ألعابه؛ دعه يختار لعبة للمشاركة.', 'استخدم التناوب بالمؤقت.', 'امدح كل مشاركة.', 'كن قدوة في العطاء، وأشركه في الصدقة.'], 'الإيثار')
p('سلوك', 'عدم احترام الكبار والرد بوقاحة', 'يرد على والديه أو معلميه بأسلوب غير لائق.', 'يزيد هذا السلوك إذا كان التعامل في البيت حاداً، أو إذا نجح الرد الوقح في الحصول على ما يريد.', ['حافظ على هدوئك ولا ترد بالمثل.', 'قل بحزم: «يمكنك أن تختلف معي باحترام».', 'لا تكمل الحديث حتى يتكلم بأدب.', 'كن قدوة في احترامه هو أيضاً.', 'علّمه «وقل لهما قولاً كريماً».'], 'بر الوالدين')
p('سلوك', 'الفوضى وعدم ترتيب الغرفة', 'يترك أغراضه مبعثرة.', 'الترتيب مهارة تُتعلّم بالتدريج والتكرار، ويحتاج الطفل خطوات واضحة لا أمراً عاماً.', ['قسّم المهمة: «الكتب على الرف، والملابس في السلة».', 'رتّبوا معاً في البداية.', 'صناديق ملصقة بصور لكل نوع.', 'روتين ترتيب ١٠ دقائق قبل النوم.', 'عاقبة منطقية: اللعبة غير المرتبة تُحفظ يوماً.'], 'النظافة')
p('سلوك', 'كثرة الطلبات والإلحاح على الشراء', 'يلحّ في السوق ويبكي حتى يُشترى له.', 'إذا نجح الإلحاح مرة واحدة تعلّم الطفل أن يكرره؛ والاتفاق المسبق يقلل الصراع.', ['اتفق معه قبل الخروج على ما سيُشترى.', 'لا تشترِ بسبب البكاء.', 'قائمة أمنيات يكتب فيها ما يريد للمناسبات.', 'مصروف يدّخر منه لما يريد.', 'علّمه القناعة وشكر النعمة.'], 'القناعة', [['خلاص خذ وسكت', 'اتفقنا اليوم على الخبز فقط، نكتبها في قائمة أمنياتك']])

# ---------- المشاعر ----------
p('مشاعر', 'الخوف والقلق', 'يخاف من الظلام أو الوحدة أو أشياء معينة.', 'مخاوف الظلام والانفصال والحيوانات طبيعية في أعمار معينة، وتزيد بالسخرية أو التخويف.', ['لا تسخر من خوفه، واسمعه.', 'علّمه أذكار النوم والمعوذات ليشعر بالحماية.', 'واجه الخوف بالتدريج لا بالإجبار.', 'لا تخوّفه لتسكيته.', 'إن طال أو أعاق حياته فاستشر مختصاً.'], 'المعوذات')
p('مشاعر', 'الخجل والانطواء', 'يرفض الكلام مع الناس ويختبئ خلف والديه.', 'الخجل طبع لا عيب، وكثير من الأطفال يحتاجون وقتاً للتأقلم. والضغط عليه أو وصفه بالخجول أمام الناس يرسّخه.', ['لا تصفه بـ«الخجول» أمام الآخرين.', 'أعطه وقتاً للتأقلم في المكان الجديد.', 'درّبه بالتمثيل على التحية والسلام.', 'لقاءات مع طفل واحد قبل المجموعات.', 'امدح كل خطوة جريئة.'], 'الحياء')
p('مشاعر', 'ضعف الثقة بالنفس', 'يقول «ما أقدر» ويتجنب المحاولة.', 'الثقة تُبنى من تجارب النجاح الصغيرة ومن المدح المحدد للجهد، وتنهدم بالنقد المستمر والمقارنة والحماية الزائدة.', ['أعطه مهاماً تناسب عمره ينجح فيها.', 'امدح الجهد لا النتيجة فقط.', 'لا تُكمل عنه ما يقدر عليه.', 'اسمح له بالخطأ وعلّمه أن الخطأ طريق التعلم.', 'اكتشف موهبته ونمّها.'], 'المؤمن القوي', [['أنت ما تعرف، هات أسويها', 'جرّب، وأنا هنا إذا احتجت']])
p('مشاعر', 'الحزن بعد فقد أو وفاة', 'تأثر بوفاة قريب أو فقد صديق أو حيوان.', 'الأطفال يحزنون بطريقة مختلفة: قد يبدون طبيعيين ثم يحزنون فجأة، وإخفاء الحقيقة عنهم يزيد القلق.', ['أخبره الحقيقة بكلمات بسيطة صادقة.', 'اسمح له بالبكاء والسؤال.', 'كن قدوة: «إن العين تدمع والقلب يحزن…».', 'حافظ على روتينه اليومي.', 'علّمه الدعاء للميت.', 'إن استمر الحزن الشديد أشهراً فاستشر مختصاً.'], 'الصبر')
p('مشاعر', 'التأثر بالخلافات الزوجية أو الطلاق', 'يبدو قلقاً أو عدوانياً أو تراجع دراسياً بعد خلاف الوالدين.', 'الخلاف نفسه ليس هو الأشد ضرراً، بل الصراخ أمام الطفل وجعله طرفاً أو رسولاً بين الوالدين.', ['لا تتشاجروا أمامه، وإن حدث فليرَ الصلح أيضاً.', 'لا تذمّ الطرف الآخر أمامه.', 'لا تجعله رسولاً ولا جاسوساً.', 'طمئنه أن الخلاف ليس بسببه وأن كليكما يحبه.', 'حافظوا على روتين ثابت.', 'في الطلاق: اتفقا على قواعد تربية مشتركة.'], 'الإصلاح')
p('مشاعر', 'الغيرة من المولود الجديد', 'يتراجع للتصرفات الطفولية أو يؤذي المولود.', 'شعور طبيعي بالخوف من فقدان المكانة والحب، والتراجع المؤقت (كطلب الحفاض) شائع.', ['هيّئه قبل الولادة، واجعل المولود «هدية منه».', 'خصّص له وقتاً يومياً معك وحده.', 'أشركه في رعاية المولود.', 'لا تقل «أنت كبرت، اتركه»، بل اذكر مزايا كونه الأكبر.', 'اطلب من الزوار الاهتمام به أولاً.'], 'العدل بين الأولاد')
p('مشاعر', 'التعرّض للتنمّر', 'يُضايَق أو يُسخر منه في المدرسة.', 'من علاماته: رفض الذهاب للمدرسة، والصداع المتكرر، وفقدان الأغراض، والعزلة. والتدخل المبكر مهم لأن التنمر يرتبط بالقلق والاكتئاب.', ['استمع له بهدوء وصدّقه.', 'لا تلمه، ولا تقل «اضربه».', 'تواصل مع المدرسة كتابياً.', 'درّبه على الرد الواثق والابتعاد وطلب المساعدة.', 'قوّ صداقاته الإيجابية ومواهبه.', 'راقب أي تنمر إلكتروني.'], 'الظلم')

# ---------- الدراسة ----------
p('دراسة', 'رفض المذاكرة والواجبات', 'يماطل ويبكي عند المذاكرة.', 'الطفل يكره المذاكرة غالباً لأنها صارت مرتبطة بالصراخ والتوتر، أو لأن المهمة أطول من قدرة تركيزه.', ['وقت ومكان ثابتان للمذاكرة بلا شاشات.', 'قسّم الوقت: ٢٠ دقيقة ثم ٥ استراحة.', 'ابدأ بالأسهل ليشعر بالإنجاز.', 'اجلس قريباً للدعم لا للحل بدلاً عنه.', 'لا تصرخ؛ إن توترت فخذوا استراحة.', 'كافئ الإنجاز بوقت لعب.'], 'العلم', [['أنت غبي ما تفهم!', 'هذا صعب فعلاً، تعال نجرب بطريقة ثانية']])
p('دراسة', 'ضعف التحصيل الدراسي', 'درجاته منخفضة رغم المحاولة.', 'قد يكون السبب نقص نوم، أو ضعف بصر أو سمع، أو صعوبة تعلم محددة (كعسر القراءة)، أو مشكلة نفسية، وليس الكسل دائماً.', ['افحص النظر والسمع.', 'تأكد من نومه الكافي وإفطاره.', 'تواصل مع المعلم لمعرفة مواطن الضعف.', 'إن كانت الصعوبة في القراءة أو الكتابة أو الحساب تحديداً فاطلب تقييم «صعوبات التعلم».', 'قارن الطفل بنفسه لا بغيره.'], 'العلم')
p('دراسة', 'قلق الاختبارات', 'يتوتر بشدة قبل الاختبار وينسى ما ذاكره.', 'القلق الشديد يعطّل الذاكرة العاملة، والطفل يلتقط توتر والديه حول الدرجات.', ['خفّف التركيز على الدرجة، وركّز على الاستعداد.', 'مذاكرة موزعة لا ليلة الاختبار.', 'نوم كافٍ ليلة الاختبار.', 'علّمه التنفس البطيء ودعاء: «اللهم لا سهل إلا ما جعلته سهلاً».', 'بعد الاختبار: لا تحقيق، بل «كيف كان شعورك؟».'], 'التوكل')
p('دراسة', 'رفض الذهاب للمدرسة', 'يبكي أو يشكو ألماً كل صباح.', 'غالباً خلفه سبب: تنمر، أو صعوبة دراسية، أو قلق انفصال، أو مشكلة مع معلم.', ['ابحث عن السبب بهدوء.', 'تواصل مع المدرسة.', 'لا تسمح بالغياب إلا لسبب صحي حقيقي.', 'روتين صباحي هادئ ومبكر.', 'استشر مختصاً إن استمر أسابيع.'], 'العلم')
p('دراسة', 'كثرة النسيان وضياع الأغراض', 'ينسى واجباته وأدواته.', 'مهارات التنظيم (الوظائف التنفيذية) تنمو تدريجياً حتى العشرينات، وتحتاج إلى أدوات مساعدة.', ['قائمة مصورة على الباب لما يحتاجه كل يوم.', 'تجهيز الحقيبة ليلاً.', 'مكان ثابت لكل شيء.', 'أعطه المسؤولية تدريجياً ودعه يتحمل نتيجة النسيان أحياناً.'], 'المسؤولية')

# ---------- العبادة ----------
p('عبادة', 'التكاسل عن الصلاة', 'يؤخر الصلاة أو يتهرب منها.', 'العادة تُبنى بالتكرار المحبوب، والارتباط بالعقاب والصراخ يُنفّر. والقدوة أقوى مؤثر.', ['صلِّ أمامه وخذه للمسجد معك.', 'من السابعة: جدول صلاة بالنجوم ومكافأة أسبوعية.', 'ذكّره بلطف قبل الوقت بدقائق.', 'اربطها بمعناها: «نكلم الله».', 'من العاشرة: حزم مع حوار وبلا إهانة.', 'امدح المواظبة أمام الأسرة.'], 'الصلاة', [['قم صلِّ يا كسلان!', 'الأذان أذّن، يلا نتوضأ ونصلي سوا']])
p('عبادة', 'الملل من حفظ القرآن', 'يتضايق من الحفظ ويرفضه.', 'الحفظ يثبت بالتكرار القصير المتباعد أكثر من الجلسات الطويلة، والارتباط بالمتعة والإنجاز يحفّز.', ['جلسات قصيرة ١٠–١٥ دقيقة يومياً.', 'استمع معه لقارئ يحبه.', 'افهموا معاني الآيات بقصة.', 'لوحة إنجاز لكل سورة يتمها.', 'احتفل بختم كل جزء.', 'استعن بقسم «زاد البراعم» في التطبيق.'], 'القرآن')
p('عبادة', 'أسئلة الطفل الصعبة عن الله والموت', 'يسأل: أين الله؟ ماذا بعد الموت؟', 'السؤال دليل تفكير صحي، والإجابة الصادقة البسيطة تبني الإيمان، والزجر يدفعه للبحث في مكان آخر.', ['رحّب بالسؤال: «سؤال جميل!».', 'أجب بالقرآن والسنة وبلغة عمره.', 'قل «لا أعرف، نبحث معاً» إن لم تعرف.', 'لا تخوّفه، بل ابدأ برحمة الله.', 'استعن بقسم «ما لا يسع المسلم جهله».'], 'الإيمان')
p('عبادة', 'الصيام الأول للطفل', 'يريد الصيام أو يصعب عليه.', 'الصيام تدريب تدريجي قبل البلوغ، وصحة الطفل أولوية.', ['ابدأ بصيام ساعات ثم نصف يوم.', 'سحور مغذٍّ وشرب ماء كافٍ.', 'أشغله وقت العصر بلعب هادئ كما كان الصحابة يفعلون.', 'احتفل بأول يوم كامل.', 'أفطره فوراً إن ظهر عليه تعب شديد أو كان مريضاً.'], 'الصيام')

# ---------- المراهقة ----------
p('مراهقة', 'التمرّد ورفض النصيحة', 'يرفض التوجيه ويجادل كثيراً.', 'المراهق يبني هويته المستقلة، والدماغ العاطفي عنده أنشط من دماغ الضبط والتخطيط؛ فالأمر المباشر يثير المقاومة، والحوار يفتح الباب.', ['حوّل الأوامر إلى حوار واسأل عن رأيه.', 'اتفقوا على قواعد قليلة واضحة مع عواقبها.', 'اختر معاركك؛ تجاوز الصغائر.', 'استمع أكثر مما تتكلم.', 'وقت خاص معه: مشوار أو رياضة.', 'تذكّر أن الشاب الذي حاوره النبي ﷺ تغيّر بالحوار والدعاء.'], 'الحوار', [['لأني قلت كذا وبس', 'خلّني أسمع رأيك، ثم أقول لك سبب قلقي']], '١٢+')
p('مراهقة', 'العزلة وكثرة الجلوس في الغرفة', 'لا يجلس مع الأسرة ويغلق بابه.', 'حاجة المراهق للخصوصية طبيعية، لكن العزلة التامة مع الحزن وتغيّر النوم والأكل وفقدان الاهتمام قد تكون علامة اكتئاب تحتاج مختصاً.', ['احترم خصوصيته مع وقت عائلي ثابت (وجبة يومية).', 'ادخل عالمه: اسأل عن اهتماماته.', 'لا تحوّل كل حديث إلى نصيحة.', 'انتبه لعلامات الاكتئاب واستشر مختصاً إن ظهرت.'], 'الأسرة', [], '١٢+')
p('مراهقة', 'أصدقاء السوء', 'تغيّر سلوكه بعد صحبة معينة.', 'تأثير الأقران في المراهقة قوي جداً، والمنع المباشر غالباً يزيد التمسك بهم.', ['اعرف أصدقاءه وأهلهم، وادعُهم للبيت.', 'لا تهاجم الصديق مباشرة؛ ناقش السلوك.', 'وفّر بيئات صحبة صالحة: نادٍ، حلقة، رياضة.', 'قوِّ علاقتك به لتكون مرجعه الأول.', '«المرء على دين خليله».'], 'الصحبة', [], '١٠+')
p('مراهقة', 'التغيرات الجسدية والبلوغ', 'ارتباك من تغيرات الجسم والأسئلة المحرجة.', 'إذا لم يسمع المراهق المعلومة الصحيحة من والديه بحياء وعلم، بحث عنها في مصادر خاطئة.', ['هيّئه قبل البلوغ بسنة أو سنتين.', 'الأب مع الولد والأم مع البنت.', 'علّمه أحكام الطهارة والغسل وعلامات البلوغ.', 'أجب بصدق وبقدر السؤال.', 'استعن بقسم «زاد الرفيق» و«زاد الرفيقة».'], 'البلوغ', [], '٩–١٤')
p('مراهقة', 'التعلق بالمشاهير والموضة', 'يقلد مشاهير في اللبس والكلام.', 'المراهق يبحث عن نماذج يتماهى معها، والفراغ الحقيقي هو غياب القدوة القريبة.', ['قدّم له نماذج ملهمة من السيرة والصحابة ومن الناجحين المعاصرين.', 'ناقش القيم خلف التقليد لا الشكل فقط.', 'أعطه مساحة اختيار في المباح.', 'كن أنت قدوة يُعجب بها.'], 'القدوة', [], '١٢+')
p('مراهقة', 'المشاعر العاطفية والإعجاب', 'تعلق عاطفي بالجنس الآخر أو محادثات خفية.', 'المشاعر في المراهقة طبيعية بسبب التغيرات الهرمونية، والمهم توجيهها لا إنكارها، والقرب من الوالدين يحمي.', ['لا تصدم ولا تفضح؛ حاور بهدوء.', 'اعترف بالمشاعر ووجّه السلوك.', 'بيّن الحكم الشرعي برفق وأسبابه.', 'اشغله بأهداف ونشاطات.', 'راقب الأجهزة باتفاق واضح.', 'للشباب: «يا معشر الشباب…».'], 'العفة', [], '١٢+')

# ---------- الشاشات والأمان ----------
p('أمان', 'إدمان الشاشات والألعاب الإلكترونية', 'غضب شديد عند سحب الجهاز وانشغال دائم به.', 'الألعاب والمقاطع القصيرة مصممة لإفراز «الدوبامين» بشكل متكرر، فيصعب التوقف. وكثرتها ترتبط بقلة النوم وضعف الانتباه.', ['لا شاشات قبل سنتين، وساعة على الأكثر حتى الخامسة.', 'لا أجهزة في غرف النوم ليلاً.', 'تنبيه قبل انتهاء الوقت بـ١٠ دقائق.', 'وفّر بدائل: لعب، ورياضة، وقراءة، وزيارات.', 'اتفقوا جميعاً على قواعد واضحة، وكونوا قدوة.'], 'اللهو')
p('أمان', 'المحتوى غير المناسب على الإنترنت', 'شاهد محتوى عنيفاً أو إباحياً.', 'التعرّض المبكر للمحتوى الإباحي يؤثر في نظرة الطفل للجسد والعلاقات، والإنكار الغاضب يجعله يخفي ما يحدث.', ['ابقَ هادئاً واشكره إن أخبرك.', 'بيّن بلطف أن هذا ضار وحرام ولماذا.', 'فعّل الرقابة الأبوية وفلترة المحتوى.', 'الأجهزة في الأماكن المشتركة.', 'حوار دوري مفتوح: «أخبرني إن رأيت شيئاً أزعجك».'], 'غض البصر')
p('أمان', 'الحماية من التحرش', 'كيف أحمي طفلي من التحرش؟', 'معظم حالات التحرش تحدث من أشخاص يعرفهم الطفل، والطفل الذي يعرف قواعد جسده ويثق بوالديه يكون أكثر أماناً.', ['علّمه أسماء أعضاء جسده الصحيحة وأن العورة لا يلمسها أحد.', 'قاعدة: لا أسرار عن الوالدين، والسر المحرج يُقال لأمي وأبي.', 'لا تجبره على تقبيل أو حضن أحد.', 'اعرف من يخلو به: سائق، عامل، قريب.', 'صدّقه دائماً إن أخبرك، وتواصل مع الجهات المختصة.'], 'العورة')
p('أمان', 'التواصل مع الغرباء في الألعاب', 'يتحدث مع أشخاص مجهولين عبر الألعاب.', 'كثير من المتحرشين والمحتالين يستخدمون الألعاب الجماعية والمحادثات للوصول إلى الأطفال.', ['أغلق المحادثة مع الغرباء في إعدادات اللعبة.', 'علّمه: لا معلومات ولا صور ولا لقاءات.', 'أي طلب سرّي أو صورة: يخبرك فوراً.', 'العب معه أحياناً لتعرف عالمه.'], 'الأمانة')

# ---------- الإخوة ----------
p('إخوة', 'الغيرة بين الإخوة', 'تنافس وغيرة مستمرة.', 'شعور طبيعي يزيد مع قدوم مولود جديد أو التفضيل.', ['اعدل في العطاء والمدح والوقت.', 'خصّص لكل طفل وقتاً منفرداً معك.', 'لا تقارن بين الأولاد أبداً.', 'أشرك الكبير في رعاية المولود ليشعر بالمكانة.'], 'العدل بين الأولاد')
p('إخوة', 'الشجار الدائم بين الإخوة', 'خلافات وصراخ وضرب متكرر.', 'تدخّل الوالدين الدائم كقاضٍ يزيد الشجار أحياناً؛ لأن الأطفال يتنافسون على انتباههم.', ['في الخلاف البسيط: اتركهم يحلونه وراقب من بعيد.', 'في الضرب: افصل فوراً بلا محاكمة طويلة.', 'علّمهم مهارة الحل: كل واحد يقول ما يريد، ثم يقترحون حلاً.', 'قواعد بيت واضحة للجميع.', 'امدحهم حين يلعبون بسلام.'], 'الإصلاح')
p('إخوة', 'تحميل الابن الأكبر مسؤوليات فوق طاقته', 'الكبير يربي إخوته ويتحمل أخطاءهم.', 'إعطاء الكبير دور الوالد يحرمه من طفولته ويولّد ضغطاً واستياءً من إخوته.', ['مسؤوليات تناسب عمره فقط.', 'لا تحاسبه على أخطاء إخوته.', 'امنحه امتيازات تناسب مسؤولياته.', 'اشكره على مساعدته ولا تعتبرها واجباً دائماً.'], 'العدل')

# ---------- العادات والصحة ----------
p('عادات', 'مصّ الإصبع وقضم الأظافر', 'عادة متكررة خاصة عند التوتر.', 'وسيلة تهدئة ذاتية، وتختفي غالباً مع العمر، والتركيز عليها والانتقاد يزيدها.', ['تجاهلها عند الصغير، وانتبه لأسباب التوتر.', 'أشغل يديه بنشاط.', 'تذكير خفي متفق عليه بدل التوبيخ.', 'مكافأة على الأيام الخالية.', 'استشر طبيب الأسنان إن استمرت بعد ظهور الأسنان الدائمة.'], 'الرفق')
p('عادات', 'السمنة وقلة الحركة', 'زيادة الوزن وقلة النشاط.', 'نمط حياة الأسرة يحدد عادات الطفل؛ والتركيز على الصحة والحركة أنفع من الحمية والحديث عن الوزن.', ['غيّروا عادات الأسرة كلها لا الطفل وحده.', 'ساعة حركة يومياً على الأقل.', 'ماء بدل العصائر والمشروبات الغازية.', 'لا تجعل الطعام مكافأة أو عقاباً.', 'لا تعلّق على شكله؛ تكلم عن الصحة.', 'راجع طبيب الأطفال لمتابعة النمو.'], 'الطعام')
p('عادات', 'إهمال النظافة الشخصية', 'يرفض الاستحمام وتنظيف الأسنان.', 'العادات اليومية تحتاج روتيناً ثابتاً وتذكيراً، والمراهق يحتاج معلومة عن تغيّرات جسمه.', ['روتين ثابت مرتبط بأوقات معينة.', 'اجعلها ممتعة للصغار: أغنية أو مؤقت.', 'اربطها بالسنة: «الطهور شطر الإيمان»، والسواك.', 'للمراهق: حوار عن تغيرات البلوغ ومزيل العرق.'], 'النظافة')
p('عادات', 'تحمّل المسؤولية والاعتماد على النفس', 'يعتمد على والديه في كل شيء.', 'الحماية الزائدة والقيام بكل شيء عن الطفل تُضعف مهاراته وثقته، والمسؤولية تُبنى بالمهام الصغيرة المتدرجة.', ['مهام منزلية حسب العمر: ٣ سنوات يرتب ألعابه، ٦ يجهز حقيبته، ١٠ يساعد في الطبخ.', 'دعه يحاول ولو أخطأ.', 'لا تُعِد ما فعله إن لم يكن متقناً تماماً.', 'اشكره على مساهمته.', '«كلكم راعٍ».'], 'المسؤولية')
p('عادات', 'تبذير المال وعدم تقدير قيمته', 'يطلب كثيراً ولا يقدّر ما عنده.', 'الطفل يتعلم قيمة المال حين يديره بنفسه ويرى أثر قراراته.', ['مصروف ثابت مناسب للعمر.', 'ثلاث حصالات: للإنفاق، والادخار، والصدقة.', 'دعه يدّخر لشيء يريده.', 'أشركه في ميزانية بسيطة للبيت.', '«ولا تبذر تبذيراً».'], 'الإسراف')
p('عادات', 'قلة النوم عند المراهق', 'يسهر حتى الفجر وينام في النهار.', 'ساعة المراهق البيولوجية تتأخر طبيعياً، لكن الشاشات ليلاً تزيد التأخير، وقلة النوم تؤثر في المزاج والتحصيل.', ['اتفاق على وقت تُغلق فيه الأجهزة.', 'الأجهزة تُشحن خارج غرفة النوم.', 'صلاة الفجر مع الأسرة تثبّت الإيقاع.', 'تجنب المنبهات (القهوة ومشروبات الطاقة) مساءً.', 'المراهق يحتاج ٨–١٠ ساعات نوم.'], 'النوم', [], '١٢+')

# ================= الدفعة الثانية =================
p('صغار', 'كثرة البكاء والأنين', 'يطلب كل شيء بالبكاء والأنين.', 'الأنين يستمر إذا كان هو الطريق الوحيد الذي يُلبّى به الطلب.', ['قل بهدوء: «أسمعك أكثر بصوتك العادي».', 'لبِّ الطلب المعقول فور طلبه بصوت هادئ.', 'تجاهل الأنين نفسه دون تجاهل الطفل.', 'تحقق من الجوع والنعاس والتعب.'], 'الرفق', [['بطّل نِق!', 'قلها بصوتك الطبيعي وأنا أسمعك']], '٢–٦')
p('صغار', 'الخوف من الطبيب والإبر', 'يصرخ ويرفض الكشف.', 'الخوف من الألم والمجهول طبيعي، والكذب عليه يجعل الزيارة التالية أصعب.', ['أخبره بالحقيقة ببساطة قبلها بقليل.', 'العب معه لعبة «الطبيب» في البيت.', 'احمله وضمّه وقت الإبرة.', 'امدح شجاعته بعدها وأعطه شيئاً يحبه.'], 'الصبر', [], '١–٧')
p('صغار', 'رفض مشاركة السرير أو النوم في غرفته', 'يرفض النوم وحده.', 'الانتقال للنوم المستقل يحتاج تدرجاً، والتفريق في المضاجع من العاشرة سنة نبوية.', ['اجعل غرفته جذابة ومريحة.', 'اجلس بجانبه أولاً، ثم ابتعد تدريجياً كل ليلة.', 'روتين نوم ثابت مع الأذكار.', 'امدحه صباحاً على نومه وحده.'], 'النوم', [], '٣–١٠')
p('صغار', 'الطفل الذي يقاطع الكلام دائماً', 'يقاطع والديه في الحديث والهاتف.', 'الصغير لا يقدّر الوقت بعد، ويحتاج إشارة واضحة أنه سيُسمع.', ['علّمه إشارة: يضع يده على يدك وتضغط عليها أنت: «رأيتك».', 'التفت إليه بعد لحظات فعلاً.', 'امدحه حين ينتظر.', 'جهّز له نشاطاً قبل مكالمة طويلة.'], 'الأدب', [], '٣–٧')
p('سلوك', 'الطفل الذي يتهم الآخرين دائماً', 'يقول دائماً: «هو اللي بدأ».', 'إلقاء اللوم يحمي الطفل من العقاب ومن الشعور بالذنب، ويقل إذا شعر أن الخطأ فرصة للإصلاح لا للفضيحة.', ['ركّز على الإصلاح لا على من بدأ.', 'اسأل: «ما الذي تقدر أنت تفعله الآن؟».', 'كن قدوة في الاعتراف بخطئك.', 'امدح الاعتراف.'], 'الاعتراف')
p('سلوك', 'التمارض والتحجج للتهرب', 'يشتكي من ألم كلما طُلب منه شيء.', 'قد يكون ألماً حقيقياً من القلق (فالقلق يسبب مغصاً وصداعاً فعلاً)، أو وسيلة للهروب من مهمة صعبة.', ['خذ الشكوى بجدية وافحصه، وراجع الطبيب إن تكررت.', 'ابحث عما يتهرب منه.', 'لا تجعل المرض مكافأة (شاشات طوال اليوم).', 'ساعده في مواجهة المهمة الصعبة بخطوات صغيرة.'], 'الصدق')
p('سلوك', 'الطفل المدلّل الذي لا يقبل «لا»', 'يغضب بشدة عند الرفض.', 'إذا اعتاد الطفل أن «لا» تتحول إلى «نعم» مع الإلحاح، صارت كل «لا» بداية معركة.', ['قل «لا» قليلاً، لكن إذا قلتها فالتزم بها.', 'اشرح السبب مرة واحدة باختصار.', 'اتفق مع الزوج والأجداد على موقف واحد.', 'تقبّل غضبه دون أن تتراجع.', 'علّمه الصبر والقناعة بالقصص والقدوة.'], 'القناعة', [['طيب طيب خذه بس اسكت', 'فاهم إنك زعلان، والجواب لا يزال لا']])
p('سلوك', 'التخريب وتكسير الأغراض', 'يكسر الألعاب والأثاث.', 'عند الصغار غالباً فضول واستكشاف، وعند الأكبر قد يكون تعبيراً عن غضب أو طلباً للاهتمام.', ['فرّق بين الاستكشاف والتخريب المقصود.', 'وفّر ألعاب فك وتركيب.', 'عاقبة منطقية: يصلح أو يساهم من مصروفه.', 'علّمه طرقاً آمنة لتفريغ الغضب: رياضة، رسم.'], 'الإصلاح')
p('سلوك', 'الطفل الكثير الأسئلة', 'يسأل «لماذا؟» بلا توقف.', 'الأسئلة علامة ذكاء ونمو، ويتراجع الفضول إذا قوبل بالزجر.', ['أجب بإيجاز، واسأله: «وأنت ما رأيك؟».', 'إن كنت مشغولاً: «سؤال رائع، نبحث عنه بعد العشاء».', 'ابحثوا معاً في كتاب أو التطبيق.', 'لا تسخر من أي سؤال.'], 'العلم')
p('سلوك', 'السلوك السيئ أمام الضيوف أو في الأماكن العامة', 'يفتعل المشاكل أمام الناس.', 'الطفل يلاحظ أن والديه يتراخيان أمام الناس، أو يشعر بالملل والإهمال وقت الزيارة.', ['اتفق معه قبل الخروج على القواعد والمكافأة.', 'جهّز نشاطاً يشغله.', 'خذه جانباً بهدوء عند الخطأ ولا توبّخه أمام الناس.', 'نفّذ العاقبة المتفق عليها في البيت.'], 'الأدب')
p('مشاعر', 'الحساسية الزائدة وسرعة البكاء', 'يبكي من أبسط تعليق.', 'بعض الأطفال مزاجهم حساس بطبيعتهم، وهذه ليست ضعفاً، ويحتاجون إلى مساعدة في تسمية مشاعرهم وتنظيمها.', ['لا تقل «أنت حساس زيادة».', 'سمِّ الشعور واعترف به.', 'علّمه التنفس العميق وطرق التهدئة.', 'قلّل النقد العلني.', 'نمِّ نقاط قوته؛ فالحساس غالباً رحيم ومبدع.'], 'الرحمة')
p('مشاعر', 'كثرة الشكوى والتذمّر', 'يتذمّر من كل شيء.', 'التذمّر عادة تُكتسب من البيئة، والتدرب على الامتنان يغيّر طريقة التفكير مع الوقت.', ['كن قدوة: قلّل التذمّر أمامه.', 'لعبة يومية على العشاء: «ثلاث نِعَم اليوم».', 'إذا اشتكى قل: «ما الحل الذي تقترحه؟».', 'علّمه «الحمد لله على كل حال».'], 'الشكر')
p('مشاعر', 'الطفل الذي يخاف الفشل ويرفض المنافسة', 'ينسحب من المسابقات خوفاً من الخسارة.', 'التركيز الزائد على النتائج والمدح بـ«أنت ذكي» يجعل الطفل يخاف أن يفقد هذا الوصف، فيتجنب التحدي.', ['امدح الجهد والمحاولة.', 'احكِ له عن أخطائك وكيف تعلمت منها.', 'العبوا ألعاباً فيها ربح وخسارة.', 'اجعل الخسارة فرصة: «ماذا تعلمنا؟».'], 'الصبر')
p('مشاعر', 'الكوابيس والأحلام المزعجة', 'يستيقظ خائفاً من حلم.', 'الكوابيس شائعة بين ٣ و٦ سنوات، وتزيد مع المشاهد المخيفة والتوتر.', ['اهدأ واحضنه وطمئنه.', 'علّمه السنة: يتفل عن يساره ثلاثاً، ويستعيذ بالله، ويتحول لجنبه الآخر، ولا يحدّث بها.', 'تجنب المشاهد المخيفة مساءً.', 'إن تكررت كثيراً مع ضيق نهاري فاستشر مختصاً.'], 'الرؤيا')
p('مشاعر', 'الطفل بعد الانتقال لبيت أو مدرسة جديدة', 'حزين أو متوتر بعد التغيير.', 'التغيير يفقد الطفل إحساسه بالأمان المألوف، ويحتاج وقتاً من أسابيع لأشهر للتأقلم.', ['هيّئه قبل الانتقال وزوروا المكان.', 'حافظ على روتين البيت كما هو.', 'ساعده على التواصل مع أصدقائه القدامى.', 'شجّعه على صداقة جديدة واحدة أولاً.'], 'الصبر')
p('دراسة', 'ضعف القراءة والكتابة', 'يقرأ ببطء ويخطئ كثيراً.', 'القراءة مهارة تتطلب تدريباً يومياً، وقد تكون هناك صعوبة تعلّم محددة (عسر القراءة) تحتاج تقييماً.', ['القراءة المشتركة ١٥ دقيقة يومياً.', 'كتب يحبها ولو قصص مصورة.', 'اقرأ أمامه؛ القدوة تصنع القارئ.', 'استعن بقسم «زاد الكبار والأميين» وتمارين الحروف.', 'إن استمرت الصعوبة رغم التدريب فاطلب تقييماً متخصصاً.'], 'القراءة')
p('دراسة', 'الغش في الاختبارات', 'ضُبط وهو يغش.', 'الغش يزيد مع الضغط الشديد على الدرجات والخوف من العقاب.', ['تحدّث عن الأمانة: «من غشنا فليس منا».', 'خفّف الضغط على الدرجة وركز على التعلّم.', 'ساعده على الاستعداد الجيد.', 'دعه يتحمل العاقبة المدرسية، وكن داعماً لا فاضحاً.'], 'الغش')
p('دراسة', 'الاعتماد الكامل على الوالدين في الواجبات', 'لا يحل واجبه إلا وأحد والديه معه.', 'الحل بدلاً عنه يعطيه رسالة أنه غير قادر، ويحرمه من مهارة التعلم الذاتي.', ['قل: «ابدأ وحدك، وأنا أراجع معك بعد ٢٠ دقيقة».', 'ساعده بالسؤال لا بالإجابة.', 'زد استقلاليته تدريجياً.', 'امدح ما حلّه وحده.'], 'المسؤولية')
p('عبادة', 'الطفل الذي يستعجل في الصلاة وينقرها', 'يصلي بسرعة دون خشوع.', 'الخشوع يُتعلم بالفهم والقدوة، وليس بالانتقاد المتكرر.', ['علّمه معنى ما يقول في الصلاة.', 'صلِّ معه جماعة وأطِل قليلاً.', 'حديث المسيء صلاته: علّمه الطمأنينة بلطف.', 'امدح الصلاة الهادئة.'], 'الخشوع')
p('عبادة', 'الملل من الذهاب للمسجد', 'يرفض الذهاب للمسجد أو يلعب فيه.', 'المسجد يصبح محبوباً إذا ارتبط بتجربة جميلة وبالترحيب لا بالزجر.', ['خذه في الأوقات القصيرة (المغرب).', 'علّمه آداب المسجد قبل الذهاب.', 'كافئه بعدها: مشوار أو حلوى.', 'عرّفه على أطفال المسجد والإمام.'], 'المسجد')
p('عبادة', 'التشكيك والأسئلة الإلحادية عند المراهق', 'يطرح شبهات عن وجود الله أو الدين.', 'المراهق يتعرض لشبهات كثيرة عبر الإنترنت، والانفعال أو التخويف يغلق باب الحوار.', ['اشكره أنه سألك أنت.', 'لا تنفعل ولا تتهمه.', 'ابحثوا معاً في الأدلة: قسم «الدعوة إلى الله» في التطبيق فيه ردود على اللادينيين بالحجة.', 'اربطه بطالب علم ثقة.', 'اهتم بالجانب العاطفي: هل وراء السؤال ضيق أو أزمة؟'], 'الإيمان', [], '١٣+')
p('مراهقة', 'المراهق الكثير الغضب', 'ينفجر غاضباً لأسباب بسيطة.', 'التغيرات الهرمونية ونشاط مراكز الانفعال تجعل المراهق أسرع انفعالاً، لكنه يتعلم الضبط بالتدريب والقدوة.', ['لا تنفعل معه؛ أجّل الحديث حتى يهدأ.', 'علّمه الهدي النبوي في الغضب.', 'الرياضة تفرغ التوتر.', 'ابحث عن أسباب: ضغط دراسي، أصدقاء، قلة نوم.', 'إن صاحبه إيذاء للنفس أو للآخرين فاستشر مختصاً فوراً.'], 'الغضب', [], '١٢+')
p('مراهقة', 'التدخين أو التجربة الخطرة', 'اكتشفت أنه يدخن أو يجرب شيئاً خطراً.', 'المراهق يجرب بدافع الفضول وضغط الأقران وإثبات الذات، والتعامل الهادئ يفتح الحوار والتعامل العنيف يدفعه للإخفاء.', ['اهدأ واجمع المعلومات أولاً.', 'تحاور عن الأضرار الصحية والحكم الشرعي.', 'ضع حدوداً واضحة وعواقب.', 'اعرف أصدقاءه ومصادر الحصول عليه.', 'في المخدرات: اطلب مساعدة مختصة فوراً.'], 'الخمر', [], '١٢+')
p('مراهقة', 'المراهق الذي لا يتحدث مع والديه', 'إجاباته «عادي، ماشي، ولا شي».', 'المراهق يتحدث أكثر في المواقف الجانبية (في السيارة، أثناء نشاط) لا في جلسات التحقيق المباشر.', ['استغل أوقات السيارة والمشي.', 'اسأل أسئلة مفتوحة محددة.', 'استمع بلا مقاطعة ولا وعظ فوري.', 'شاركه أنت قصصك وأخطاءك.'], 'الحوار', [], '١٢+')
p('مراهقة', 'هوس المظهر والوزن عند المراهقين', 'قلق شديد من شكله ووزنه.', 'المقارنة بصور المؤثرين المعدّلة ترتبط بعدم الرضا عن الجسم، وقد تتطور لاضطرابات أكل.', ['لا تعلّق على وزنه أو شكله ولا وزن غيره.', 'ركّز على الصحة والقوة لا الشكل.', 'ناقش حقيقة الصور المعدّلة.', 'إن لاحظت تقييداً شديداً للأكل أو تقيؤاً فاستشر طبيباً فوراً.'], 'الشكر', [], '١٢+')
p('أمان', 'الطفل الذي يُترك مع الخادمة طويلاً', 'يقضي معظم وقته مع العاملة المنزلية.', 'الطفل يتعلق بمن يقضي معه الوقت ويكتسب لغته وقيمه، والتربية لا تُفوّض كاملة.', ['حدّد دور العاملة بالخدمة لا بالتربية.', 'وقت يومي ثابت للأم والأب مع الطفل.', 'لا تتركه يخلو معها أو مع السائق لفترات طويلة.', 'راقب ما يشاهده ويسمعه.'], 'الرعاية')
p('أمان', 'تصوير الأطفال ونشر صورهم', 'نشر صور الأطفال في وسائل التواصل.', 'صور الأطفال المنشورة قد تُسرق أو تُستغل، وتبقى رقمياً مدى الحياة دون إذنهم.', ['لا تنشر صوراً تكشف المدرسة أو المكان أو العورة.', 'اجعل حساباتك خاصة.', 'اسأل الطفل الأكبر قبل النشر.', 'علّم أولادك ألا ينشروا صورهم وصور غيرهم.'], 'الستر')
p('إخوة', 'التفضيل غير المقصود لأحد الأبناء', 'يشعر أحدهم أن أخاه المفضّل.', 'حتى لو لم تقصد، فإن الطفل يلتقط فروق النبرة والوقت والمدح.', ['اسأل كل ابن: «هل تشعر أني أفضّل أحداً؟».', 'وقت خاص لكل واحد.', 'لا تقارن.', 'العدل في الهدايا واجب: «اعدلوا بين أولادكم».'], 'العدل بين الأولاد')
p('إخوة', 'الأخ الذي يتسلّط على أخواته', 'يتحكم بأخواته ويقسو عليهن باسم الرجولة.', 'القوامة والرجولة الحقيقية حماية ورحمة لا تسلّط، والطفل يتعلم ذلك من معاملة الأب للأم.', ['علّمه أن الرجولة رحمة وحماية.', 'لا تمنحه سلطة على أخواته.', 'الأب قدوة في احترام الأم والبنات.', '«خيركم خيركم لأهله».'], 'الرحمة')
p('عادات', 'الإدمان على السكريات والوجبات السريعة', 'يرفض الطعام الصحي.', 'الأطعمة المصنّعة مصممة لتكون مرغوبة جداً، والذوق يتعود تدريجياً على الطعام الصحي.', ['لا تشترِها للبيت أصلاً.', 'خيارات صحية متاحة دائماً (فواكه، مكسرات للأكبر).', 'الحلوى في أوقات محددة لا مكافأة.', 'اطبخوا معاً وجبات صحية لذيذة.'], 'الطعام')
p('عادات', 'كثرة المزاح الجارح والسخرية', 'يسخر من الآخرين ويجرحهم بالمزاح.', 'يتعلم الطفل السخرية من البيت والمقاطع الكوميدية، ولا يدرك أثرها دون توجيه.', ['بيّن الفرق بين المزاح والسخرية.', '﴿لا يسخر قوم من قوم﴾.', 'اطلب منه الاعتذار.', 'كن قدوة: لا سخرية في البيت.'], 'السخرية')
p('عادات', 'عدم الوفاء بالوعود والمواعيد', 'لا يلتزم بما يتفق عليه.', 'الالتزام يتعلمه الطفل من وفاء والديه بوعودهم له أولاً.', ['أوفِ أنت بوعودك له.', 'اكتبوا الاتفاقات.', 'عواقب واضحة عند عدم الالتزام.', 'امدح الوفاء.', '«آية المنافق ثلاث…».'], 'الوعد')
p('عادات', 'اللغة: ضعف العربية وكثرة الكلام بالإنجليزية', 'لا يتقن العربية ويتكلم الإنجليزية غالباً.', 'اللغة الأم تُحفظ بالاستعمال اليومي، والأطفال قادرون على إتقان أكثر من لغة إذا كان لكل لغة مساحتها.', ['العربية لغة البيت.', 'قصص عربية يومياً ورسوم كرتونية بالفصحى.', 'حفظ القرآن والأناشيد.', 'استعن بقسم «علوم العربية» للكبار.'], 'العربية')
